-- Core Accounting, Buying and Stock verticals.
CREATE TABLE IF NOT EXISTS purchase_order_progress_entries (
  tenant_id TEXT NOT NULL,
  voucher_type TEXT NOT NULL,
  voucher_no TEXT NOT NULL,
  voucher_revision INTEGER NOT NULL,
  line_key TEXT NOT NULL,
  purchase_order TEXT NOT NULL,
  kind TEXT NOT NULL CHECK (kind IN ('Receipt','Billing')),
  item_code TEXT NOT NULL,
  qty_micros INTEGER NOT NULL,
  posting_at TEXT NOT NULL,
  PRIMARY KEY (tenant_id,voucher_type,voucher_no,voucher_revision,line_key)
);
CREATE INDEX IF NOT EXISTS idx_po_progress_reference ON purchase_order_progress_entries(tenant_id,purchase_order,kind,item_code,posting_at);

CREATE TRIGGER IF NOT EXISTS purchase_progress_reference_guard
BEFORE INSERT ON purchase_order_progress_entries
BEGIN
  SELECT CASE
    WHEN NOT EXISTS (
      SELECT 1 FROM documents WHERE tenant_id=NEW.tenant_id
        AND doc_key='Purchase Order:' || NEW.purchase_order AND doctype='Purchase Order' AND docstatus=1
    ) THEN RAISE(ABORT,'PURCHASE_REFERENCE_SOURCE_NOT_FOUND')
    WHEN NOT EXISTS (
      SELECT 1 FROM document_children WHERE tenant_id=NEW.tenant_id
        AND parent_key='Purchase Order:' || NEW.purchase_order AND fieldname='items'
        AND json_extract(payload_json,'$.item_code')=NEW.item_code
    ) THEN RAISE(ABORT,'PURCHASE_REFERENCE_ITEM_NOT_FOUND')
    WHEN COALESCE((SELECT SUM(qty_micros) FROM purchase_order_progress_entries
      WHERE tenant_id=NEW.tenant_id AND purchase_order=NEW.purchase_order AND kind=NEW.kind AND item_code=NEW.item_code),0)+NEW.qty_micros < 0
      THEN RAISE(ABORT,'PURCHASE_REFERENCE_QUANTITY_NEGATIVE')
    WHEN COALESCE((SELECT SUM(qty_micros) FROM purchase_order_progress_entries
      WHERE tenant_id=NEW.tenant_id AND purchase_order=NEW.purchase_order AND kind=NEW.kind AND item_code=NEW.item_code),0)+NEW.qty_micros >
      (SELECT COALESCE(SUM(CAST(json_extract(payload_json,'$.qty_micros') AS INTEGER)),0) FROM document_children
       WHERE tenant_id=NEW.tenant_id AND parent_key='Purchase Order:' || NEW.purchase_order AND fieldname='items'
       AND json_extract(payload_json,'$.item_code')=NEW.item_code)
      THEN RAISE(ABORT,'PURCHASE_REFERENCE_QUANTITY_EXCEEDED')
  END;
END;

CREATE TRIGGER IF NOT EXISTS purchase_order_cancel_reference_guard
BEFORE INSERT ON mutation_guard
WHEN NEW.action='cancel'
 AND (SELECT doctype FROM documents WHERE tenant_id=NEW.tenant_id AND doc_key=NEW.doc_key)='Purchase Order'
 AND COALESCE((SELECT SUM(qty_micros) FROM purchase_order_progress_entries WHERE tenant_id=NEW.tenant_id
   AND purchase_order=(SELECT name FROM documents WHERE tenant_id=NEW.tenant_id AND doc_key=NEW.doc_key)),0) != 0
BEGIN SELECT RAISE(ABORT,'ACTIVE_PURCHASE_PROGRESS_EXISTS'); END;

CREATE TRIGGER IF NOT EXISTS purchase_invoice_cancel_payment_guard
BEFORE INSERT ON mutation_guard
WHEN NEW.action='cancel'
 AND (SELECT doctype FROM documents WHERE tenant_id=NEW.tenant_id AND doc_key=NEW.doc_key)='Purchase Invoice'
 AND COALESCE((SELECT SUM(amount_minor) FROM payment_ledger_entries WHERE tenant_id=NEW.tenant_id
   AND against_voucher_type='Purchase Invoice' AND against_voucher_no=(SELECT name FROM documents WHERE tenant_id=NEW.tenant_id AND doc_key=NEW.doc_key)),0)
   != COALESCE(CAST((SELECT json_extract(payload_json,'$.grand_total_minor') FROM documents WHERE tenant_id=NEW.tenant_id AND doc_key=NEW.doc_key) AS INTEGER),0)
BEGIN SELECT RAISE(ABORT,'ACTIVE_SUPPLIER_PAYMENT_ALLOCATIONS'); END;

CREATE VIEW IF NOT EXISTS payable_outstanding AS
SELECT tenant_id,party,currency,currency_scale,against_voucher_type,against_voucher_no,
       SUM(amount_minor) AS outstanding_minor,SUM(base_amount_minor) AS base_outstanding_minor,
       CAST(SUM(amount_minor) AS REAL)/CASE currency_scale WHEN 0 THEN 1 WHEN 1 THEN 10 WHEN 2 THEN 100 WHEN 3 THEN 1000 WHEN 4 THEN 10000 WHEN 5 THEN 100000 ELSE 1000000 END AS outstanding_amount
FROM payment_ledger_entries WHERE account_type='Payable'
GROUP BY tenant_id,party,currency,currency_scale,against_voucher_type,against_voucher_no;

CREATE VIEW IF NOT EXISTS general_ledger_report AS
SELECT tenant_id,posting_at,voucher_type,voucher_no,account,party_type,party,currency,currency_scale,
       CAST(debit_minor AS REAL)/CASE currency_scale WHEN 0 THEN 1 WHEN 1 THEN 10 WHEN 2 THEN 100 WHEN 3 THEN 1000 WHEN 4 THEN 10000 WHEN 5 THEN 100000 ELSE 1000000 END AS debit,
       CAST(credit_minor AS REAL)/CASE currency_scale WHEN 0 THEN 1 WHEN 1 THEN 10 WHEN 2 THEN 100 WHEN 3 THEN 1000 WHEN 4 THEN 10000 WHEN 5 THEN 100000 ELSE 1000000 END AS credit,
       cost_center
FROM gl_entries;

CREATE VIEW IF NOT EXISTS trial_balance AS
SELECT tenant_id,account,currency,currency_scale,
       CAST(SUM(debit_minor) AS REAL)/CASE currency_scale WHEN 0 THEN 1 WHEN 1 THEN 10 WHEN 2 THEN 100 WHEN 3 THEN 1000 WHEN 4 THEN 10000 WHEN 5 THEN 100000 ELSE 1000000 END AS debit,
       CAST(SUM(credit_minor) AS REAL)/CASE currency_scale WHEN 0 THEN 1 WHEN 1 THEN 10 WHEN 2 THEN 100 WHEN 3 THEN 1000 WHEN 4 THEN 10000 WHEN 5 THEN 100000 ELSE 1000000 END AS credit,
       CAST(SUM(debit_minor-credit_minor) AS REAL)/CASE currency_scale WHEN 0 THEN 1 WHEN 1 THEN 10 WHEN 2 THEN 100 WHEN 3 THEN 1000 WHEN 4 THEN 10000 WHEN 5 THEN 100000 ELSE 1000000 END AS balance
FROM gl_entries GROUP BY tenant_id,account,currency,currency_scale;

