-- Immutable standard catalog source. Tenant provisioning copies from this
-- catalog so non-demo Workers do not depend on hard-coded demo metadata.
INSERT OR IGNORE INTO doctype_definitions
SELECT '__standard__',doctype,module,is_custom,is_submittable,is_child,revision,metadata_json,disabled,modified_by,modified_at
FROM doctype_definitions WHERE tenant_id='demo';
INSERT OR IGNORE INTO print_formats
SELECT '__standard__',name,doc_type,is_default,disabled,revision,format_json,modified_by,modified_at
FROM print_formats WHERE tenant_id='demo';
